
public class demo1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		for(int i = 1; i<=3; i++) {
			for(int j= 1;j<=5;j++) {
				System.out.println(j);
			}
			System.out.println();
		}
		int i = 1;
		while(i<=3) {
			int j = 1;
			while(j<=5) {
				System.out.println(j);
				j++;
			}
			System.out.println();
			i++;
			
		}
	}

}
